('VERBS.pdf', 'idiom', 'Stick With (Something) Take Advantage Of (Someone Or Something) Take Care Of (Someone Or Something) Take Out (Something) Or Take (Something)', null, null, null, 'SEGUIR CON', 'To continue doing something, to not quit something', 'The boy has been able to stick with his music lessons since he was a child. - TOMAR VENTAJAW 8SYWIWSQISRISVWSQIXLMRKJSVSRIŞWS[RFIRIƙX  We took advantage of the beautiful weather and went to the beach. - CUIDAR To look after or give attention to someone or something  It is good to take care of your health or you will become sick.', null, 24, 'STICK WITH (SOMETHING) - SEGUIR CON TAKE ADVANTAGE OF (SOMEONE OR SOMETHING) TAKE CARE OF (SOMEONE OR SOMETHING) TAKE OUT (SOMETHING) OR TAKE (SOMETHING)'),
('VERBS.pdf', 'idiom', 'Out Take Over (Something) Or Take (Something)', null, null, null, 'REMOVER', 'To remove something from somewhere', 'The teacher told us to take out our books.', null, 25, 'OUT - REMOVER TAKE OVER (SOMETHING) OR TAKE (SOMETHING)'),
('VERBS.pdf', 'idiom', 'Over', null, null, null, 'TOMAR EL CONTROL', 'To take control of something, to take command of something', 'The large company wants to take over the small company in our town.', null, 25, 'OVER - TOMAR EL CONTROL'),
('VERBS.pdf', 'idiom', 'Take Place', null, null, null, 'OCURRIR', 'To happen, to occur', 'The soccer game took place on the coldest day of the year.', null, 25, 'TAKE PLACE - OCURRIR'),
('VERBS.pdf', 'idiom', 'To The Extent That', null, null, null, 'EN LA MEDIDA EN QUE', 'To the degree that, in so far as', 'I plan to provide information about the new company policy, to the extent  that I am familiar with it.', null, 25, 'TO THE EXTENT THAT - EN LA MEDIDA EN QUE'),
